// Junta todas las filas de la hoja en un solo texto para la IA.
const filas = $input.all().map(function (item) { return item.json; });

// Limite prudente: las 200 filas mas recientes (ajustalo a tu hoja).
const hasta = Date.now();
const desde = hasta - 7 * 86400000;
const semana = filas.filter(f => {
  const fecha = Date.parse(f.fecha || f.created_at || f.fecha_entrada || '');
  return Number.isFinite(fecha) && fecha >= desde && fecha <= hasta;
}).sort((a,b) => Date.parse(a.fecha || a.created_at || a.fecha_entrada) - Date.parse(b.fecha || b.created_at || b.fecha_entrada));
const recorte = semana.slice(-200);
if (!recorte.length) throw new Error('No hay filas con fecha válida de los últimos 7 días. Configura la columna fecha.');
const lineas = recorte.map(function (f) { return JSON.stringify(f); }).join('\n');

const sistema = 'Eres analista de operaciones y redactas en espanol, con tuteo profesional. ' +
  'A partir de las filas de registro que te paso, escribe el resumen semanal para el equipo: ' +
  '1) que ha pasado esta semana en 3-4 frases; ' +
  '2) las cifras clave que se deduzcan de las filas (totales, repartos), citando de que columna salen; ' +
  '3) puntos de atencion: maximo 3, solo si los datos los sostienen; ' +
  '4) que conviene mirar la semana que viene. ' +
  'Prohibido inventar datos que no esten en las filas. Si algo no se puede saber con estos datos, dilo. ' +
  'Formato: texto plano de correo, sin markdown, maximo 300 palabras.';

const payload = {
  model: 'claude-sonnet-5',
  max_tokens: 1200,
  system: sistema,
  messages: [ { role: 'user', content: 'Periodo: últimos 7 días. Filas analizadas: ' + recorte.length + '; omitidas por límite: ' + Math.max(0, semana.length-recorte.length) + '. Filas del registro (una por linea, en JSON):\n' + lineas } ]
};

return [ { json: { payload: payload, totalFilas: recorte.length, filasDisponibles: semana.length, filasOmitidas: Math.max(0, semana.length - recorte.length) } } ];

// Recoge el texto redactado y el numero de filas analizadas.
const bruto = ($json.content && $json.content[0] && $json.content[0].text) ? $json.content[0].text : 'La IA no devolvio texto. Revisa la ejecucion en n8n.';
const total = $('Compactar filas').first().json.totalFilas;

return [ { json: { resumen: bruto.trim(), totalFilas: total } } ];
